head.b:skin:
/* OpenCodeWEB — Self-Sovereign Open Source | opencodeweb.blogspot.com */
*{box-sizing:border-box;margin:0;padding:0}
:root{--bg:#020617;--panel:#0f172a;--card:rgba(15,23,42,.55);--line:#1e293b;--txt:#f1f5f9;--mut:#94a3b8;--vio:#a78bfa;--cy:#22d3ee;--em:#34d399;--am:#fbbf24}
body{background:var(--bg);color:var(--txt);font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;min-height:100vh;-webkit-font-smoothing:antialiased}
a{color:var(--cy);text-decoration:none}
a:hover{text-decoration:underline}
.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
.wrap{max-width:72rem;margin:0 auto;padding:0 1rem}
/* header */
.topbar{position:sticky;top:0;z-index:50;background:rgba(2,6,23,.85);backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}
.topbar-in{display:flex;align-items:center;justify-content:space-between;gap:1rem;height:4rem}
.brand{display:flex;align-items:center;gap:.75rem}
.brand:hover{text-decoration:none}
.logo{width:2.25rem;height:2.25rem;border-radius:.75rem;background:linear-gradient(135deg,#8b5cf6,#d946ef,#22d3ee);display:flex;align-items:center;justify-content:center;color:#020617;font-weight:800}
.brand b{font-size:1.15rem;letter-spacing:-.02em;background:linear-gradient(90deg,#a78bfa,#f0abfc,#67e8f9);-webkit-background-clip:text;background-clip:text;color:transparent}
.brand small{display:block;font-size:.68rem;color:var(--mut)}
.nav{display:flex;align-items:center;gap:.25rem;font-size:.9rem;font-weight:500}
.nav a{color:#cbd5e1;padding:.4rem .65rem;border-radius:.5rem}
.nav a:hover{background:#1e293b;color:#fff;text-decoration:none}
.btn{display:inline-flex;align-items:center;gap:.4rem;padding:.45rem .9rem;border-radius:.6rem;background:#1e293b;color:#e2e8f0;font-size:.85rem;font-weight:600}
.btn:hover{background:#334155;text-decoration:none;color:#fff}
/* hero */
.hero{border-bottom:1px solid var(--line);background-image:linear-gradient(rgba(148,163,184,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(148,163,184,.06) 1px,transparent 1px);background-size:42px 42px;text-align:center;padding:3.5rem 1rem}
.hero .pills{display:flex;justify-content:center;flex-wrap:wrap;gap:.5rem;margin-bottom:1rem}
.pill{font-size:.72rem;padding:.3rem .8rem;border-radius:9999px;border:1px solid}
.pill.g{color:#6ee7b7;border-color:rgba(52,211,153,.25);background:rgba(52,211,153,.08)}
.pill.v{color:#c4b5fd;border-color:rgba(167,139,250,.25);background:rgba(167,139,250,.08)}
.pill.c{color:#67e8f9;border-color:rgba(34,211,238,.25);background:rgba(34,211,238,.08)}
.pill.a{color:#fcd34d;border-color:rgba(251,191,36,.25);background:rgba(251,191,36,.08)}
#Header1 h1{font-size:2.4rem;font-weight:800;letter-spacing:-.02em;line-height:1.15}
#Header1 h1 a{background:linear-gradient(90deg,#a78bfa,#f0abfc,#67e8f9);-webkit-background-clip:text;background-clip:text;color:transparent}
#Header1 h1 a:hover{text-decoration:none}
#Header1 .description{color:var(--mut);margin-top:.6rem;font-size:1rem}
.hero-links{margin-top:1.4rem;display:flex;justify-content:center;flex-wrap:wrap;gap:.6rem}
.hero-links a{font-size:.8rem;padding:.45rem .9rem;border-radius:.6rem;border:1px solid var(--line);background:var(--card);color:#e2e8f0}
.hero-links a:hover{border-color:var(--vio);text-decoration:none}
/* layout */
.content{display:grid;grid-template-columns:1fr;gap:2rem;padding:2.5rem 0}
@media(min-width:900px){.content{grid-template-columns:minmax(0,1fr) 300px}}
/* posts */
.post{background:var(--card);border:1px solid var(--line);border-radius:1rem;padding:1.5rem;margin-bottom:1.5rem}
.post h2,.post h3.post-title{font-size:1.4rem;font-weight:800;letter-spacing:-.01em}
.post h2 a,.post h3.post-title a,.post-title a{color:var(--txt)}
.post h2 a:hover,.post-title a:hover{color:var(--vio);text-decoration:none}
.post-header{margin-bottom:.6rem}
.post-timestamp{font-size:.75rem;color:var(--mut)}
.post-body{color:#cbd5e1;font-size:.95rem;line-height:1.7}
.post-body img{max-width:100%;height:auto;border-radius:.6rem}
.post-body pre{background:#020617;border:1px solid var(--line);border-radius:.6rem;padding:.8rem;overflow-x:auto;font-size:.8rem}
.post-footer{margin-top:1rem;padding-top:.8rem;border-top:1px solid var(--line);font-size:.78rem;color:var(--mut);display:flex;flex-wrap:wrap;gap:.4rem 1rem}
.post-footer a{color:var(--cy)}
.post-labels a{font-size:.72rem;padding:.15rem .6rem;border-radius:9999px;background:#1e293b;color:#cbd5e1;margin-right:.3rem}
.post-labels a:hover{background:#334155;text-decoration:none}
.post-comment-link a{color:var(--em)}
.jump-link a{display:inline-block;margin-top:.8rem;padding:.4rem 1rem;border-radius:.6rem;background:linear-gradient(90deg,#7c3aed,#0891b2);color:#fff;font-weight:600;font-size:.85rem}
.jump-link a:hover{text-decoration:none;opacity:.9}
#blog-pager{margin:1rem 0;text-align:center;font-size:.85rem}
#blog-pager a{color:var(--cy);margin:0 .5rem}
.comments{margin-top:1.5rem;border-top:1px solid var(--line);padding-top:1rem}
.comments h4{font-size:1rem;margin-bottom:.8rem}
.comment{border:1px solid var(--line);border-radius:.6rem;padding:.7rem;margin-bottom:.6rem;font-size:.85rem;color:#cbd5e1}
.comment-header{font-size:.75rem;color:var(--mut);margin-bottom:.3rem}
/* sidebar */
.sidebar .widget{background:var(--card);border:1px solid var(--line);border-radius:1rem;padding:1.2rem;margin-bottom:1.2rem}
.sidebar .widget h2{font-size:.8rem;text-transform:uppercase;letter-spacing:.08em;color:var(--mut);margin-bottom:.7rem}
.sidebar ul{list-style:none}
.sidebar li{padding:.3rem 0;font-size:.88rem;border-bottom:1px dashed var(--line)}
.sidebar li:last-child{border-bottom:0}
.sidebar a{color:#cbd5e1}
.sidebar a:hover{color:var(--cy)}
.cloud-label-widget-content .label-size{margin:.15rem}
.profile-img{border-radius:9999px}
/* footer */
.footer{border-top:1px solid var(--line);padding:2.2rem 0;text-align:center;color:var(--mut);font-size:.85rem}
.footer .links{display:flex;justify-content:center;flex-wrap:wrap;gap:1rem;margin:.8rem 0}
.footer a{color:var(--mut)}
.footer a:hover{color:var(--cy)}
#Attribution1{font-size:.75rem;color:#475569;margin-top:.6rem}
.status{font-size:.8rem;color:var(--mut);text-align:center;padding:.4rem}
@media(max-width:700px){.nav{display:none}#Header1 h1{font-size:1.8rem}}
